CREATE OR REPLACE PROCEDURE ret_pris(p_id integer, p_price numeric)
LANGUAGE plpgsql AS $$
BEGIN
    IF p_price IS NULL OR p_price <= 0 THEN
        RAISE EXCEPTION 'Prisen skal være positiv';
    END IF;
    UPDATE products SET price = p_price WHERE id = p_id;
END;
$$;
CALL ret_pris(1, 35);

CREATE OR REPLACE FUNCTION kontroller_pris()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.price IS NULL OR NEW.price <= 0 THEN
        RAISE EXCEPTION 'Prisen skal være positiv';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER products_price_check
BEFORE UPDATE ON products
FOR EACH ROW EXECUTE FUNCTION kontroller_pris();

